   [119]={next_id=120, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="Well, the Anchor Space is a subspace anomaly sustained by Void Particles, so only forces related to the concept of Crystals can interfere with targets inside.", msg_color="", msg_size=0, talker="玩家名字", audio="", img="arts/ui/bg/story/storybg_101.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "3101", 0, 0, -16, 180}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,0}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=1, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
