   [122]={next_id=123, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="The Anchor Space exists because of its core, and this core is usually housed within the largest Shogger in the space—what we call a Xenocryst.", msg_color="", msg_size=0, talker="玩家名字", audio="", img="arts/ui/bg/story/storybg_101.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "3101", 0, 0, -16, 180}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,0}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=1, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [123]={next_id=124, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="That's also why Shoggers can freely enter and exit Anchor Space. Xenocrysts share the same origin as the Anchor Space's constructs—they provide the energy to sustain it, while Shoggers rely on the Anchor Space to manifest in our world.", msg_color="", msg_size=0, talker="玩家名字", audio="", img="arts/ui/bg/story/storybg_101.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "3101", 0, 0, -16, 180}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,0}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=1, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
