   [125]={next_id=126, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="Exactly. Alright, that's enough review for today. This kind of dry knowledge takes repetition to stick.", msg_color="", msg_size=0, talker="玩家名字", audio="", img="arts/ui/bg/story/storybg_101.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "3101", 0, 0, -16, 180}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,0}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=1, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [126]={next_id=127, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="...Then what's the Linker's role in this?", msg_color="", msg_size=0, talker="Alicia", audio="", img="arts/ui/bg/story/storybg_101.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "3101", 0, 0, -16, 180}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=1, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [127]={next_id=128, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="Me? Aside from the D-Blood Link, I also direct some of your combat functions. That's why I need to enter the Anchor with you.", msg_color="", msg_size=0, talker="玩家名字", audio="", img="arts/ui/bg/story/storybg_101.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "3101", 0, 0, -16, 180}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,0}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=1, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [128]={next_id=129, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="In other words, we're partners.", msg_color="", msg_size=0, talker="玩家名字", audio="", img="arts/ui/bg/story/storybg_101.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "3101", 0, 0, -16, 180}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,0}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=1, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [129]={next_id=130, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="Partners... Does that mean we'll always be together, no matter what?", msg_color="", msg_size=0, talker="Alicia", audio="", img="arts/ui/bg/story/storybg_101.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "3101", 0, 0, -16, 180}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=1, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [130]={next_id=131, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="Not always. There are exceptions. There might come a time when Alicia has to fight alone inside an Anchor Space.", msg_color="", msg_size=0, talker="玩家名字", audio="", img="arts/ui/bg/story/storybg_101.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "3101", 0, 0, -16, 180}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,0}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=1, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
